def reconcile(expected_ids, submitted_ids):
    if len(submitted_ids) != len(set(submitted_ids)):
        raise ValueError('duplicate submitted ID')
    expected = set(expected_ids)
    submitted = set(submitted_ids)
    return sorted(expected - submitted), sorted(submitted - expected)

assert reconcile(['intro', 'loops'], ['loops', 'intro']) == ([], [])
assert reconcile(['intro', 'loops'], ['intro', 'files']) == (['loops'], ['files'])
try:
    reconcile(['intro'], ['intro', 'intro'])
except ValueError:
    pass
else:
    raise AssertionError('duplicate accepted')
print('inventory checks passed')

